@page "/"
@inject IShipmentService ShipmentService

<PageTitle>Track Shipment - ShipmentTracker</PageTitle>

<div class="container">
    <h1>Shipment Tracker</h1>
    <p class="lead">Track your shipment in real-time</p>

    <div class="card mb-4">
        <div class="card-body">
            <h5 class="card-title">Track a Shipment</h5>
            <div class="input-group">
                <input type="text" class="form-control" placeholder="Enter tracking number (e.g., SHP-20260708-A1B2C3D4)"
                       @bind="trackingNumber" @bind:event="oninput" @onkeydown="HandleKeyDown" />
                <button class="btn btn-primary" @onclick="TrackShipment" disabled="@isLoading">
                    @if (isLoading)
                    {
                        <span class="spinner-border spinner-border-sm me-1"></span>
                    }
                    Track
                </button>
            </div>
            @if (errorMessage is not null)
            {
                <div class="alert alert-warning mt-3">@errorMessage</div>
            }
        </div>
    </div>

    @if (trackedShipment is not null)
    {
        <div class="card">
            <div class="card-header d-flex justify-content-between align-items-center">
                <strong>@trackedShipment.TrackingNumber</strong>
                <span class="badge @GetStatusBadgeClass(trackedShipment.Status)">@trackedShipment.Status</span>
            </div>
            <div class="card-body">
                <div class="row">
                    <div class="col-md-6">
                        <p><strong>Origin:</strong> @trackedShipment.Origin</p>
                        <p><strong>Destination:</strong> @trackedShipment.Destination</p>
                        <p><strong>Recipient:</strong> @trackedShipment.RecipientName</p>
                    </div>
                    <div class="col-md-6">
                        <p><strong>Shipped:</strong> @trackedShipment.ShippedDate.ToString("MMM dd, yyyy")</p>
                        <p><strong>Estimated Delivery:</strong> @trackedShipment.EstimatedDelivery.ToString("MMM dd, yyyy")</p>
                        @if (trackedShipment.ActualDelivery.HasValue)
                        {
                            <p><strong>Delivered:</strong> @trackedShipment.ActualDelivery.Value.ToString("MMM dd, yyyy")</p>
                        }
                    </div>
                </div>
                @if (!string.IsNullOrEmpty(trackedShipment.Notes))
                {
                    <p><strong>Notes:</strong> @trackedShipment.Notes</p>
                }
            </div>
        </div>
    }
</div>

@code {
    private string trackingNumber = string.Empty;
    private Shipment? trackedShipment;
    private string? errorMessage;
    private bool isLoading;

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await TrackShipment();
    }

    private async Task TrackShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;

        isLoading = true;
        errorMessage = null;
        trackedShipment = null;

        try
        {
            trackedShipment = await ShipmentService.GetShipmentByTrackingNumberAsync(trackingNumber.Trim());
            if (trackedShipment is null)
                errorMessage = "No shipment found with that tracking number.";
        }
        catch
        {
            errorMessage = "Unable to retrieve shipment information. Please try again.";
        }
        finally
        {
            isLoading = false;
        }
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.InTransit => "bg-primary",
