    private List<Shipment>? shipments;
    private string filterText = string.Empty;
    private bool showCreate;
    private bool isSaving;
    private Shipment newShipment = new() { ShippedDate = DateTime.UtcNow, EstimatedDelivery = DateTime.UtcNow.AddDays(5) };

    private IEnumerable<Shipment> FilteredShipments =>
        shipments?.Where(s => string.IsNullOrWhiteSpace(filterText) ||
            s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase)) ?? [];

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentService.GetAllShipmentsAsync();
    }

    private void ShowCreateForm() => showCreate = true;
    private void CancelCreate() => showCreate = false;
    private void ClearFilter() => filterText = string.Empty;

    private async Task CreateShipment()
    {
        isSaving = true;
        try
        {
            var created = await ShipmentService.CreateShipmentAsync(newShipment);
            shipments?.Insert(0, created);
            newShipment = new() { ShippedDate = DateTime.UtcNow, EstimatedDelivery = DateTime.UtcNow.AddDays(5) };
            showCreate = false;
        }
        finally
        {
            isSaving = false;
        }
    }

    private async Task UpdateStatus(Shipment shipment, ChangeEventArgs e)
    {
        if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var newStatus))
        {
            var updated = await ShipmentService.UpdateShipmentStatusAsync(shipment.Id, newStatus);
            shipment.Status = updated.Status;
            shipment.ActualDelivery = updated.ActualDelivery;
        }
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-info",
        ShipmentStatus.Exception => "bg-danger",
        ShipmentStatus.PickedUp => "bg-secondary",
        _ => "bg-warning text-dark"
    };
}
